{
  "type": "object",
  "properties": {
    "claims_to_add": {
      "type": "array",
      "maxItems": 2,
      "items": {
        "type": "string",
        "minLength": 1,
        "pattern": "\\S"
      }
    },
    "hypothesis_update": {
      "type": "object",
      "properties": {
        "action": {
          "enum": [
            "keep",
            "set",
            "clear"
          ]
        },
